$dir = 'assets\images'
$ok = 0; $miss = @()
foreach ($k in $map.Keys) {
  $src = Join-Path $dir $k
  if (Test-Path -LiteralPath $src) {
    Move-Item -LiteralPath $src -Destination (Join-Path $dir $map[$k]) -Force
    $ok++
  } else { $miss += $k }
}
"renamed: $ok / $($map.Count)"
if ($miss) { "MISSING:"; $miss }
